local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["8c0547c72cead45a"] = { "Un giorno diventerò una guardia!", "." },
  ["8c0ca283a5470849"] = { "Oh, santo cielo, non di nuovo... Siediti, <giovanotto/signorina>.\n\nDi sicuro Rutgar ti ha già raccontato parte della storia, quindi ti risparmio i dettagli noiosi e vengo dritto al sodo.", "." },
  ["8c208f546b2d7ad3"] = { "Che stai facendo laggiù?", "." },
  ["8c239ff3cde7fcba"] = { "Se desideri fondare una confraternita, è dalla maestra di gilda, Lysheana, che devi andare. La troverai nella ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧, nella parte nord-orientale di Darnassus.", "." },
  ["8c27e8059789c8d8"] = { "Salute, giovane {class}. In preparazione della guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧ contro i silitidi, l'⟦Alliance=Alleanza⟧ mi ha chiesto di dirigere la raccolta di fiori di loto purpureo. Conosco molti usi di questo fiore, e così ho accettato di aiutarli a raccoglierne $2055w. Finora ne abbiamo raccolti $2053w.", "." },
  ["8c39187e37e9c8fd"] = { "Il Flagello è all'ingresso del castello! Per ⟦Stormwind=Roccavento⟧! Per re Anduin!", "." },
  ["8c397c59192d70db"] = { "Salve. Come stai?", "." },
  ["8c3ec5c24f9f8ab3"] = { "Aye, a quanto pare hai imparato parecchio, complimenti. Ma lo sai quanti vogliono diventare miei apprendisti? Facciamo così: sbrigami un piccolo lavoretto e ti prendo con me.", "." },
  ["8c433ba9d25c2b03"] = { "Usa questo ⟦Staff of Command=Bastone del Comando⟧ su Raze quando sei vicino agli Shadowsilk Poacher, e lui farà loro rimpiangere il giorno in cui hanno deciso di cacciare di frodo in queste terre.", "." },
  ["8c4d1af8978117ed"] = { "Tuo teschio va a decorare nostri altari rituali!", "." },
  ["8c5ac8cc8755e531"] = { "Ho la certezza assoluta di voler imparare la Conciatura Tribale.", "." },
  ["8c5cd5132919ae58"] = { "Desidero disimparare i miei talenti di classe o i talenti ereditari.", "." },
  ["8c6358aa2b427784"] = { "Dov'è l'anziana Predastelle?", "." },
  ["8c6681bf373fae0b"] = { "Tu grande capo adesso! Tu <re/regina>! Gloria a <re/regina> {name}, <Re/Regina> dei Gordok!\n\nOra che tu capo, tutti scagnozzi ti danno tributo! Tu lasciato qualcuno vivo, vero capo?", "." },
  ["8c6d1fcfa8f9cb06"] = { "Il ⟦Stonehearth Bunker=Fortilizio di Cordipietra⟧ è stato distrutto dall'⟦Horde=Orda⟧!", "." },
  ["8c6ff777f99fce69"] = { "Siamo salvi! I contadini sono sfuggiti al Flagello!", "." },
  ["8c789c548e810071"] = { "Quando la ⟦Darkmoon Faire=Fiera di Lunacupa⟧ aprirà, si troverà a Mulgore. Pianteremo le tende appena a sud-ovest di ⟦Thunder Bluff=Picco del Tuono⟧!", "." },
  ["8c7c43b24a269546"] = { "Contromisure anti-fuga attivate. Autodistruzione tra T meno 20 secondi....", "." },
  ["8c83580f760b1663"] = { "Stai scherzando, vero? Ok, ok, niente panico. Per fortuna, quando l'ho infuso con il componente che hai recuperato, ho creato un legame anche tra me e l'oggetto. Dovrei riuscire a localizzarlo e a richiamarlo ovunque tu l'abbia lasciato.\n\nSei <sicuro/sicura> di averlo perso? Hai guardato in tutte le borse e in banca?", "." },
  ["8c8670c051e6d377"] = { "Grazie! E quando preparo le mie bevande... non dire a nessuno con cosa sono fatte!", "." },
  ["8c871e87905b52cc"] = { "Assaggia la lama, bastardo!", "." },
  ["8c876c3454fc6e77"] = { "Hai provato la birra ⟦Dark Iron=Ferroscuro⟧? È la migliore!", "." },
  ["8c878c55f4b9e1d9"] = { "Chi sei e perché mi disturbi? Ah, giusto: <lo/la> <studente/studentessa> di pozioni. Giusto. Cosa posso fare per te?", "." },
  ["8c8841d943321bde"] = { "Vaelastrasz, non farlo!!!", "." },
  ["8c89ff6ba6642da6"] = { "Warg osserva l'acqua chiedendosi quanta fortuna avrà oggi.", "." },
  ["8c8c065f18754cc1"] = { "{name}, cosa aspetti? Trova il primo maresciallo Teravaine nel ⟦Field of Strife=Pian della Discordia⟧ e consegnagli gli ordini d'assalto. Appena li riceverà, lui e le sue truppe caricheranno l'⟦Horde=Orda⟧ senza fare prigionieri!", "." },
  ["8c9156bcb9249047"] = { "Voglio diventare fabbro d'armi.", "." },
  ["8c9325d178c8e816"] = { "Sei nel posto giusto, <ragazzo/ragazza>! La gente viene qui da tutto il mondo per imparare il mestiere del fabbro. Troverai ⟦Bengus Deepforge=Bengus Forgiafonda⟧ a martellare su un'incudine nel cuore della nostra bella città, proprio presso la ⟦Great Forge=Grande Forgia⟧.", "." },
  ["8c94d7a1e6b34dc6"] = { "Ah, <amico/amica>, aiuto solo i cacciatori e i loro famigli.", "." },
  ["8c951e23d88c5bc5"] = { "Le benedizioni del Signore del Vento scorrono in me!", "." },
  ["8c9e5d1750a198ae"] = { "Vengono a prenderti, idiota!", "." },
  ["8c9ef83b48e202a5"] = { "Ti schiaccerò il cranio sotto lo stivale!", "." },
  ["8ca35619034811fe"] = { "Perché mi chiamano \"il Distruttore\"?\r\n\nFidati, non vuoi saperlo.", "." },
  ["8ca36d50c56c6b9d"] = { "Aiutami con questo, {name}!", "." },
  ["8cacf08f1094ef3d"] = { "Immagino che sia quasi tutto finito, vero, {name}? Mi mancherai... qui sopra sarà piuttosto triste senza nessuno con cui parlare.\n\nMa questo non vuol dire che non puoi tornare a trovarmi in futuro!", "." },
  ["8cb0e42071928bbb"] = { "Ecco, è fatto. Il libro è stato potenziato...", "." },
  ["8cb2bba5028ad4f1"] = { "Aye, aveva fatto ciò che si riteneva impossibile. Dalla fenditura balzò fuori un agente di Therazane!\n\nDal mio punto di osservazione vedevo il goblin conversare con l'agente del Dio Antico. Quello che accadde dopo fu terribile...", "." },
  ["8cb363f9c80c3229"] = { "Preferisci i fucili o gli archi?", "." },
  ["8cb9677640c98f8f"] = { "Un'alimentazione adeguata tiene in vita un soldato molto dopo che le ferite del campo di battaglia avrebbero dovuto <finirlo/finirla>, {class}. Se vogliamo resistere nella Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧ che ci attende, ci serviranno tutte le provviste che riusciamo a trasportare. Qui sto raccogliendo pinnagialla maculati prima che vengano spediti.\n\nAl momento ne abbiamo $2101w, ma dobbiamo raccoglierne in tutto $2103w se vogliamo riuscire a sfamare tutti.", "." },
  ["8ccb5ddd8d1b8e78"] = { "Grazie ancora, {name}! Quello che abbiamo trovato mi soddisfa molto.\n\nBuona fortuna!", "." },
  ["8ccfc76dc7204db6"] = { "Scassinare", "." },
  ["8cd460d0c8d2abe6"] = { "Ora che hai avuto modo di studiare l'imp, passiamo al prossimo servitore che potrai evocare: l'ombra del Vuoto.", "." },
  ["8cd49d447541a630"] = { "Mordi quella lingua, {race}, o te la strappo dalla scatola cranica e la uso come scaldacorno.", "." },
  ["8cd6550310a7844c"] = { "L'e'ko è il potere che ogni creatura possiede. L'amuleto che ti ho fatto ti permette di catturarlo in una forma fisica.\n\nConosco un incantesimo che può trasformare l'e'ko che trovi e farlo diventare juju.\n\nPoi puoi prendere la ⟦Cache of Mau'ari=Cassa di Mau'ari⟧ e usarla per riflettere su di te il potere del juju.\n\nDai, prova. Porta l'e'ko a Mau'ari e ci divertiamo un po'.", "." },
  ["8cda42107a58e87b"] = { "Hai vero talento e passione per le pozioni. C'è però una piccola faccenda di cui vorrei che ti occupassi.", "." },
  ["8ce3647b73ebf366"] = { "Assicurati di passare dal Gizmotronic Apparatus a prendere un grimaldello e un E.C.A.C. Ti serviranno entrambi per portare a termine la missione!", "." },
  ["8ceaba8e021408ad"] = { "Mungimi, John.", "." },
  ["8cec70037a86cc29"] = { "A rapporto!", "." },
  ["8cf5542f45e6ce46"] = { "Oh oh... qui si mette male.", "." },
})
